import{_ as l,a0 as d,w as p,s as a,ao as r,I as s,x as i,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在 Linux 中查找文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中查找文件 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中查找文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中查找文件 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180405 How to find files in Linux","title":"如何在 Linux 中查找文件","tag":"201804","desc":""},"relativePath":"201804/20180405 How to find files in Linux.md","filePath":"[post].md"}'),u={name:"201804/20180405 How to find files in Linux.md"};function f(g,e,m,x,h,c){const t=d("Link");return p(),a("div",null,[e[22]||(e[22]=r('<h1 id="如何在-linux-中查找文件" tabindex="-1">如何在 Linux 中查找文件 <a class="header-anchor" href="#如何在-linux-中查找文件" aria-label="Permalink to “如何在 Linux 中查找文件”">​</a></h1><blockquote><p>使用簡單的命令在 Linux 下基於類型、內容等快速查找文件。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/find-file-linux-code_magnifying_glass_zero.png?itok=E2HoPDg0" alt=""></p><p>如果你是 Windows 或 OSX 的非資深用户，那麼可能使用 GUI 來查找文件。你也可能發現界面受限，令人沮喪，或者兩者兼而有之，並學會了組織文件並記住它們的確切順序。你也可以在 Linux 中做到這一點 —— 但你不必這樣做。</p><p>Linux 的好處之一是它提供了多種方式來處理。你可以打開任何文件管理器或按下 <code>Ctrl+F</code>，你也可以使用程序手動打開文件，或者你可以開始輸入字母，它會過濾當前目錄列表。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/uploads/find-files-in-linux-ctrlf.png?itok=1gf9kIut" alt="Screenshot of how to find files in Linux with Ctrl+F" title="Screenshot of how to find files in Linux with Ctrl+F"></p><p><em>使用 Ctrl+F 在 Linux 中查找文件的截圖</em></p><p>但是如果你不知道你的文件在哪裏，又不想搜索整個磁盤呢？對於這個以及其他各種情況，Linux 都很合適。</p><h3 id="按命令名查找程序位置" tabindex="-1">按命令名查找程序位置 <a class="header-anchor" href="#按命令名查找程序位置" aria-label="Permalink to “按命令名查找程序位置”">​</a></h3><p>如果你習慣隨心所欲地放文件，Linux 文件系統看起來會讓人望而生畏。對我而言，最難習慣的一件事是找到程序在哪裏。</p><p>例如，<code>which bash</code> 通常會返回 <code>/bin/bash</code>，但是如果你下載了一個程序並且它沒有出現在你的菜單中，那麼 <code>which</code> 命令就是一個很好的工具。</p><p>一個類似的工具是 <code>locate</code> 命令，我發現它對於查找配置文件很有用。我不喜歡輸入程序名稱，因為像 <code>locate php</code> 這樣的簡單程序通常會提供很多需要進一步過濾的結果。</p><p>有關 <code>locate</code> 和 <code>which</code> 的更多信息，請參閲 <code>man</code> 頁面：</p><ul><li><code>man which</code></li><li><code>man locate</code></li></ul><h3 id="find" tabindex="-1">find <a class="header-anchor" href="#find" aria-label="Permalink to “find”">​</a></h3><p><code>find</code> 工具提供了更先進的功能。以下是我安裝在許多服務器上的腳本示例，我用於確保特定模式的文件（也稱為 glob）僅存在五天，並且所有早於此的文件都將被刪除。 （自上次修改以來，分數用於保留最多 240 分鐘的偏差）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ./backup/core-files*.tar.gz -mtime +4.9 -exec rm {} \\;</span></span></code></pre></div><p><code>find</code> 工具有許多高級用法，但最常見的是對結果執行命令，而不用鏈式地按照類型、創建日期、修改日期過濾文件。</p><p><code>find</code> 的另一個有趣用處是找到所有有可執行權限的文件。這有助於確保沒有人在你昂貴的服務器上安裝比特幣挖礦程序或殭屍網絡。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find / -perm /+x</span></span></code></pre></div><p>有關 <code>find</code> 的更多信息，請使用 <code>man find</code> 參考 <code>man</code> 頁面。</p><h3 id="grep" tabindex="-1">grep <a class="header-anchor" href="#grep" aria-label="Permalink to “grep”">​</a></h3><p>想通過內容中查找文件？ Linux 已經實現了。你可以使用許多 Linux 工具來高效搜索符合模式的文件，但是 <code>grep</code> 是我經常使用的工具。</p><p>假設你有一個程序發佈代碼引用和堆棧跟蹤的錯誤消息。你要在日誌中找到這些。 <code>grep</code> 不總是最好的方法，但如果文件是一個給定的值，我經常使用 <code>grep -R</code>。</p><p>越來越多的 IDE 正在實現查找功能，但是如果你正在訪問遠程系統或出於任何原因沒有 GUI，或者如果你想在當前目錄遞歸查找，請使用：<code>grep -R {searchterm} </code> 或在支持 <code>egrep</code> 別名的系統上，只需將 <code>-e</code> 標誌添加到命令 <code>egrep -r {regex-pattern}</code>。</p>',25)),s("p",null,[e[2]||(e[2]=i("我在去年給 ",-1)),o(t,{href:"https://www.raspbian.org/"},{default:n(()=>[...e[0]||(e[0]=[i("Raspbian",-1)])]),_:1}),e[3]||(e[3]=i(" 中的 ",-1)),e[4]||(e[4]=s("code",null,"dhcpcd5",-1)),e[5]||(e[5]=i(" 打補丁時使用了這種技術，這樣我就可以在",-1)),o(t,{href:"https://www.raspberrypi.org/"},{default:n(()=>[...e[1]||(e[1]=[i("樹莓派基金會",-1)])]),_:1}),e[6]||(e[6]=i("發佈新的 Debian 時繼續操作網絡接入點了。",-1))]),e[23]||(e[23]=s("p",null,"哪些提示可幫助你在 Linux 上更有效地搜索文件？",-1)),e[24]||(e[24]=s("hr",null,null,-1)),s("p",null,[e[8]||(e[8]=i("via: ",-1)),o(t,{href:"https://opensource.com/article/18/4/how-find-files-linux"},{default:n(()=>[...e[7]||(e[7]=[i("https://opensource.com/article/18/4/how-find-files-linux",-1)])]),_:1})]),s("p",null,[e[13]||(e[13]=i("作者：",-1)),o(t,{href:"https://opensource.com/users/lewiscowles1986"},{default:n(()=>[...e[9]||(e[9]=[i("Lewis Cowles",-1)])]),_:1}),e[14]||(e[14]=i(" 選題：",-1)),o(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[10]||(e[10]=[i("lujun9972",-1)])]),_:1}),e[15]||(e[15]=i(" 譯者：",-1)),o(t,{href:"https://github.com/geekpi"},{default:n(()=>[...e[11]||(e[11]=[i("geekpi",-1)])]),_:1}),e[16]||(e[16]=i(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[12]||(e[12]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[19]||(e[19]=i("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[17]||(e[17]=[i("LCTT",-1)])]),_:1}),e[20]||(e[20]=i(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:n(()=>[...e[18]||(e[18]=[i("Linux中國",-1)])]),_:1}),e[21]||(e[21]=i(" 榮譽推出",-1))])])}const w=l(u,[["render",f]]);export{L as __pageData,w as default};
